// Edge Function "contest-export" as a single file for the Supabase dashboard editor.
// Generated by scripts/build-dashboard-functions.mjs from supabase/functions/. Do not edit by hand.
// In the dashboard: Edge Functions -> Deploy a new function -> Via Editor -> name it "contest-export",
// paste this whole file, Deploy, then switch "Verify JWT" OFF for it (this function checks the caller itself).

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2';

// ---- _shared\deps.ts
// Dependency container so handlers can be unit-tested with fakes.

interface Deps {
  env: (name: string) => string | undefined;
  /** Client acting as the logged-in user (RLS applies, auth.uid() is set). */
  userClient: (token: string) => SupabaseClient;
  /** Client with only the public anon key (for verifying a password like the browser would). */
  anon: () => SupabaseClient;
  /** Service-role client. Only for work the user must not do themselves (storage, auth admin). */
  admin: () => SupabaseClient;
  fetch: typeof fetch;
  /** Run work after the response is sent (EdgeRuntime.waitUntil); awaited inline if unavailable. */
  background: (work: Promise<unknown>) => void;
  now: () => Date;
}

function need(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new Error(`Missing function secret: ${name}`);
  return v;
}

function realDeps(): Deps {
  let admin: SupabaseClient | undefined;
  return {
    env: (n) => Deno.env.get(n),
    userClient: (token) =>
      createClient(need('SUPABASE_URL'), need('SUPABASE_ANON_KEY'), {
        global: { headers: { Authorization: `Bearer ${token}` } },
        auth: { persistSession: false, autoRefreshToken: false },
      }),
    anon: () =>
      createClient(need('SUPABASE_URL'), need('SUPABASE_ANON_KEY'), {
        auth: { persistSession: false, autoRefreshToken: false },
      }),
    admin: () =>
      (admin ??= createClient(need('SUPABASE_URL'), need('SUPABASE_SERVICE_ROLE_KEY'), {
        auth: { persistSession: false, autoRefreshToken: false },
      })),
    fetch: (...a) => fetch(...a),
    background: (work) => {
      // deno-lint-ignore no-explicit-any
      const rt = (globalThis as any).EdgeRuntime;
      const guarded = work.catch((e) => console.error('background task failed', e instanceof Error ? e.message : e));
      if (rt?.waitUntil) rt.waitUntil(guarded);
    },
    now: () => new Date(),
  };
}

/** Verifies the bearer token with Supabase Auth and returns the user id. */
async function authenticate(deps: Deps, token: string | null): Promise<{ id: string; email?: string } | null> {
  if (!token) return null;
  const { data, error } = await deps.admin().auth.getUser(token);
  if (error || !data?.user) return null;
  return { id: data.user.id, email: data.user.email };
}

// ---- _shared\csv.ts
// CSV with spreadsheet-formula protection (names and notes are user-supplied).
function csvCell(value: unknown): string {
  if (value === null || value === undefined) return '';
  let s = typeof value === 'object' ? JSON.stringify(value) : String(value);
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(columns: string[], rows: Record<string, unknown>[]): string {
  const lines = [columns.map(csvCell).join(',')];
  for (const r of rows) lines.push(columns.map((c) => csvCell(r[c])).join(','));
  return lines.join('\r\n') + '\r\n';
}

// ---- _shared\http.ts
// Small HTTP helpers shared by all Edge Functions.
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

/** Handles CORS preflight and non-POST methods. Returns a Response when the request is done. */
function gate(req: Request): Response | null {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed', message: 'Use POST.' }, 405);
  return null;
}

function bearer(req: Request): string | null {
  const h = req.headers.get('Authorization') ?? '';
  const m = /^Bearer\s+(.+)$/i.exec(h);
  return m ? m[1].trim() : null;
}

async function readJson(req: Request): Promise<Record<string, unknown> | null> {
  try {
    const body = await req.json();
    return body && typeof body === 'object' && !Array.isArray(body) ? body : null;
  } catch {
    return null;
  }
}

const STATUS_BY_CODE: Record<string, number> = {
  forbidden: 403, not_member: 403, not_found: 404, draft_not_found: 404,
  already_reviewed: 409, duplicate_reference: 409, resubmission_exists: 409, rate_limited: 429,
};

/**
 * Database errors are raised as "code: human message" (see the migrations). Known codes are passed
 * to the client; anything else is hidden behind a generic message.
 */
function dbError(error: { message?: string; code?: string; status?: number }): Response {
  const msg = error.message ?? '';
  if (error.code === 'PGRST301' || error.code === 'PGRST303' || /\bJWT\b/.test(msg)) {
    return json({ error: 'unauthorized', message: 'Please log in again.' }, 401);
  }
  const m = /^([a-z_]+): ([\s\S]*)$/.exec(msg);
  if (m) return json({ error: m[1], message: m[2] }, STATUS_BY_CODE[m[1]] ?? 400);
  if (error.code === '42501') return json({ error: 'forbidden', message: 'Not allowed.' }, 403);
  console.error('unexpected database error', error.code, msg);
  return json({ error: 'internal', message: 'Something went wrong. Please try again.' }, 500);
}

function errorResponse(code: string, message: string, status = 400): Response {
  return json({ error: code, message }, status);
}

// ---- contest-export\handler.ts
// Owner only: final-standings + audit-log CSVs, and the archive step that deletes screenshots.
// The database enforces the rules (final, 30 days, exported first); we only add the file deletion.



const PAGE = 1000;

async function handle(req: Request, deps: Deps): Promise<Response> {
  const early = gate(req);
  if (early) return early;

  const token = bearer(req);
  const caller = await authenticate(deps, token);
  if (!caller || !token) return errorResponse('unauthorized', 'Please log in again.', 401);
  const body = await readJson(req);
  const action = body?.action;
  if (action !== 'export' && action !== 'archive') return errorResponse('bad_request', 'action must be export or archive.');

  const user = deps.userClient(token);
  const { data: isOwner, error: roleErr } = await user.rpc('is_owner');
  if (roleErr) return dbError(roleErr);
  if (isOwner !== true) return errorResponse('forbidden', 'Not allowed.', 403);

  return action === 'export' ? await exportCsvs(user) : await archive(user, deps, body?.reason);
}

// deno-lint-ignore no-explicit-any
async function exportCsvs(user: any): Promise<Response> {
  const { data: standings, error } = await user.rpc('get_admin_leaderboard');
  if (error) return dbError(error);

  const audit: Record<string, unknown>[] = [];
  for (let from = 0;; from += PAGE) {
    const { data, error: aErr } = await user.from('audit_log').select('*').order('id').range(from, from + PAGE - 1);
    if (aErr) return dbError(aErr);
    audit.push(...data);
    if (data.length < PAGE) break;
  }

  // Marks the export (required before archiving). Only possible once results are final.
  const { error: markErr } = await user.rpc('owner_mark_exported');
  const marked = !markErr;
  if (markErr && !/^not_final:/.test(markErr.message)) return dbError(markErr);

  return json({
    marked,
    standings_csv: toCsv(
      ['rank', 'display_name', 'title', 'email', 'points', 'tasks_completed', 'reached_at', 'pending_count', 'active'],
      standings,
    ),
    audit_csv: toCsv(
      ['id', 'created_at', 'contest_id', 'actor_type', 'actor_id', 'action', 'entity', 'entity_id', 'reason', 'before', 'after'],
      audit,
    ),
  });
}

// deno-lint-ignore no-explicit-any
async function archive(user: any, deps: Deps, reason: unknown): Promise<Response> {
  const { data: banner, error } = await user.rpc('get_contest_banner');
  if (error) return dbError(error);
  const contest = Array.isArray(banner) ? banner[0] : banner;
  if (!contest) return errorResponse('not_found', 'Contest not found.', 404);

  // Re-running after a partial failure only needs the file purge.
  if (contest.status !== 'archived') {
    const { error: aErr } = await user.rpc('archive_contest', { p_reason: typeof reason === 'string' ? reason : '' });
    if (aErr) return dbError(aErr);
  }
  try {
    const removed = await purgeProofs(deps, contest.contest_id);
    return json({ ok: true, files_deleted: removed });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error('contest-export: screenshot purge failed', {
      contest_id: contest.contest_id,
      error: message,
    });
    return errorResponse(
      'archive_cleanup_failed',
      'The contest was archived, but screenshot cleanup failed. Retry the archive action to continue cleanup.',
      500,
    );
  }
}

/** Deletes every object under "{contest_id}/" in the proofs bucket (member folders, then files). */
async function purgeProofs(deps: Deps, contestId: string): Promise<number> {
  const bucket = deps.admin().storage.from('proofs');
  let removed = 0;
  const folders: { name: string }[] = [];
  for (let offset = 0;;) {
    const { data, error } = await bucket.list(contestId, { limit: 100, offset });
    if (error) throw new Error(`Storage folder listing failed at offset ${offset}: ${error.message}`);
    if (!data) throw new Error(`Storage folder listing returned no data at offset ${offset}.`);
    folders.push(...data);
    if (data.length < 100) break;
    offset += data.length;
  }

  for (const folder of folders) {
    const prefix = `${contestId}/${folder.name}`;
    for (;;) {
      const { data: files, error: listError } = await bucket.list(prefix, { limit: 100, offset: 0 });
      if (listError) throw new Error(`Storage file listing failed for "${prefix}": ${listError.message}`);
      if (!files) throw new Error(`Storage file listing returned no data for "${prefix}".`);
      if (!files.length) break;
      const { data: deleted, error: removeError } = await bucket.remove(
        files.map((file: { name: string }) => `${prefix}/${file.name}`),
      );
      if (removeError) throw new Error(`Storage file removal failed for "${prefix}": ${removeError.message}`);
      if (!deleted?.length) throw new Error(`Storage file removal made no progress for "${prefix}".`);
      removed += deleted.length;
    }
  }
  return removed;
}

// ---- contest-export\index.ts
const deps = realDeps();
Deno.serve((req) => handle(req, deps));
